const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const taskDrafts=new Map();
let state,blocked=false,selected=dates[0],view='home',editing=null,installPrompt,hideOptional=false,hideDone=false;
try{state=read();}catch(e){state=defaults();blocked=true;}
const weekday=d=>new Intl.DateTimeFormat('en',{weekday:'short',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z')).toUpperCase();
const list=d=>sorted(state.events.filter(x=>x.date===d).map(resolveEvent)).map(normalize);
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function status(){ $('#save-status').textContent=blocked?'저장 중단 · 설정 확인':navigator.onLine?'이 기기에 저장 · 자동 저장':'오프라인 · 이 기기에 저장'; }
function commit(next){if(blocked){toast('기존 저장 데이터를 보호하고 있습니다. 설정에서 백업 후 복원해 주세요.');return false;}try{state=write(next,state);status();toast('이 기기에 저장했습니다');return true;}catch(e){$('#save-status').textContent='저장 실패 · 변경 미반영';toast(e.message||'저장하지 못했습니다. 저장 공간을 확인해 주세요.');return false;}}
const clone=()=>structuredClone(state);
function mapLinks(raw){const event=state.events.some(e=>e.id===raw.id);const x=normalize(raw),urls=mapURLs(x);return `<div class="actions map-actions"><a href="${esc(urls.map)}" target="_blank" rel="noopener noreferrer">${icon('map')}지도 보기 ↗</a><a href="${esc(urls.directions)}" target="_blank" rel="noopener noreferrer">${icon('directions')}길찾기 ↗</a>${!event&&urls.street?`<a class="street-action" href="${esc(urls.street)}" target="_blank" rel="noopener noreferrer">${icon('street')}Street View ↗</a>`:''}${(event?[]:['origin','destination']).map(k=>{const url=streetURL(x[k+'StreetViewUrl']);return url?`<a class="street-action" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${icon('street')}${k==='origin'?'출발지':'도착지'} Street View ↗</a>`:'';}).join('')}${!event&&!urls.street&&!streetURL(x.originStreetViewUrl)&&!streetURL(x.destinationStreetViewUrl)?'<span class="street-hint meta">Street View URL 또는 좌표를 편집에서 등록해 주세요.</span>':''}${x.address?`<button data-copy="${esc(x.address)}">주소 복사</button>`:''}</div>`;}
function dday(){const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const n=Math.round((Date.parse(dates[0])-Date.parse(today))/86400000);return n>0?`D−${n}`:n>=-13?`DAY ${1-n}`:'FIN';}
function home(){return `<div class="home-layout">${homeHero(dday())}<section><div class="section-heading"><h2>The journey</h2><small>DECEMBER, 2026</small></div>${dates.map((d,i)=>`<details class="day-row"><summary><span class="day-date">12.${d.slice(-2)}<small>${weekday(d)}</small></span><span class="city">${esc(dayCities(d))}</span></summary><div class="day-content"><span class="eyebrow">DAY ${String(i+1).padStart(2,'0')}</span>${summaryHTML(d,true)}${list(d).length?list(d).map(e=>`<p>${esc(e.start||'시간 미정')} &nbsp; ${esc(e.title)}</p>`).join(''):'<p class="muted">아직 날짜에 배치한 일정이 없습니다.</p>'}<button class="text-link" data-day="${d}">이날의 일정 보기 →</button></div></details>`).join('')}<button class="text-link" data-day="">날짜 미정 장소 ${list('').length}곳 살펴보기 →</button></section></div>`;}
function eventHTML(raw,idx,items){const e=normalize(raw),v=visual(e);const peers=list(e.date),p=peers.findIndex(x=>x.id===e.id);return `${eventStart(e,true)}${detailHTML(e)}${e.reservationId?reservationContext(e.reservationId):''}${attachmentsHTML(e)}${streetEmbed(e)}${linkedChecks('events',e.id)}${mediaHTML(e)}${localHTML(e)}${['official','website','instagramUrl'].filter(k=>e[k]).map(k=>`<a class="text-link" href="${esc(e[k])}" target="_blank" rel="noopener noreferrer">${k==='official'?'공식 교통정보':k==='instagramUrl'?'Instagram':'예약 / 홈페이지'} ↗</a>`).join('')}<div class="event-actions">${mapLinks(e)}<button data-transfer="${esc(e.id)}" data-copy-event="0">날짜 이동</button><button data-transfer="${esc(e.id)}" data-copy-event="1">날짜 복사</button>${peers.length>1?`<button data-move="-1" data-id="${esc(e.id)}" ${p===0?'disabled':''} aria-label="${esc(e.title)} 위로">↑</button><button data-move="1" data-id="${esc(e.id)}" ${p===peers.length-1?'disabled':''} aria-label="${esc(e.title)} 아래로">↓</button>`:''}</div></div></article>`;}
function itinerary(){const all=list(selected),items=all.filter(e=>!hideOptional||!['선택','확인만','대체 코스','방문 취소'].includes(e.condition));return `<p class="eyebrow">YOUR DAYS, YOUR PACE</p><h1 class="page-title">The itinerary.</h1><p class="muted page-intro">계획은 가볍게, 기억은 오래.</p><div class="dates" aria-label="여행 날짜">${dates.map(d=>`<button class="date ${d===selected?'active':''}" data-select="${d}" aria-pressed="${d===selected}"><span>${weekday(d)}</span><b>${d.slice(-2)}</b><small>${esc(list(d).map(e=>e.title).join(' · ')||'일정 없음')}</small></button>`).join('')}<button class="date ${selected===''?'active':''}" data-select="" aria-pressed="${selected===''}"><span>UNPLANNED</span>날짜 미정</button></div><div class="section-heading"><div><h2>${selected?esc(dayCities(selected)):'Places to go'}</h2><p class="meta">${selected?selected.replaceAll('-','.'):'방문 예정 · 날짜를 직접 지정해 주세요'} / ${items.length}개의 일정</p></div><button class="primary" data-add="events">+ 일정 추가</button></div><div class="actions"><button data-shift="-1">← 이전 날짜</button><button data-today="1">오늘</button><button data-shift="1">다음 날짜 →</button><button data-optional="1">${hideOptional?'선택·대체 일정 표시':'선택·대체 일정 숨기기'}</button>${selected?'<button data-daynote="1">하루 요약 입력</button>':''}</div>${all.some(e=>Number.isFinite(e.sortOrder))?'<p class="hint">수동 순서로 표시 중입니다. 시작 시간이 달라도 지정한 순서를 유지합니다.</p>':''}${summaryHTML(selected)}${state.bookings.filter(b=>b.linkedDate===selected&&!state.events.some(e=>e.date===selected&&e.reservationId===b.id)).map(linkedBooking).join('')}<div class="timeline">${items.length?items.map((e,i)=>eventHTML(e,i,items)).join(''):'<div class="empty">아직 비어 있는 하루입니다.<br>새 일정을 추가하거나 ‘날짜 미정’ 장소를 선택해 날짜를 지정하세요.</div>'}</div><p class="hint">지도·길찾기·외부 이미지는 인터넷 연결이 필요합니다.<br>이동 시간과 비용은 직접 확인하여 입력해 주세요.</p>`;}
function bookings(){return `<p class="eyebrow">A PLACE TO REST, A WAY TO GO</p><h1 class="page-title">Stay & booking.</h1><div class="notice">예약 정보는 이 브라우저에 저장됩니다. 동기화 연결 후에는 로그인 계정의 다른 기기에도 반영됩니다. 이미지·PDF 원본은 전체 ZIP 백업으로 옮겨 주세요. 여권·카드 번호는 입력하지 마세요.</div><div class="section-heading"><h2>Your reservations</h2><button class="primary" data-add="bookings">+ 예약 추가</button></div>${state.bookings.map(b=>`<article class="booking"><div class="booking-header"><div><span class="eyebrow">${esc(b.city)} / ${esc(b.type)}</span>${bookingHeading(b)}</div><button data-edit="bookings" data-id="${esc(b.id)}">수정 ↗</button></div><p class="meta">${icon('clock')}${esc(b.checkin||'날짜 미정')} — ${esc(b.checkout||'미정')} · ${esc(b.status||'미정')}</p>${['address','instructions','note','checkinTime','checkoutTime','access','origin','destination','serviceNumber'].filter(k=>b[k]).map(k=>`<p>${icon(['checkinTime','checkoutTime'].includes(k)?'clock':['origin','destination','address'].includes(k)?'pin':k==='serviceNumber'?bookingIcon(b):'ticket')}${esc(({instructions:'체크인 안내: ',contact:'연락처: ',reference:'예약번호: ',note:'메모: ',address:'주소: ',checkinTime:b.type==='숙소'?'체크인 시간: ':'출발 시간: ',checkoutTime:b.type==='숙소'?'체크아웃 시간: ':'도착 시간: ',access:'접근 방법: ',origin:'출발: ',destination:'도착: ',serviceNumber:'편명 / 열차: '}[k])+b[k])}</p>`).join('')}<details><summary>예약 상세 정보</summary><p>${icon('ticket')}예약번호: ${esc(b.reference||'미입력')} · 연락처: ${esc(b.contact||'미입력')}</p></details><button data-connect-booking="${esc(b.id)}">일정에 연결</button><span class="meta">${esc(state.events.filter(e=>e.reservationId===b.id).map(e=>e.date).join(' · '))}</span>${b.linkedDate?`<button data-day="${esc(b.linkedDate)}">연결 일정 보기 →</button>`:''}${attachmentsHTML(b)}${linkedChecks('bookings',b.id)}${mediaHTML(b)}${localHTML(b)}${b.checkin?`<button data-day="${esc(b.checkin)}">이날의 일정 보기 →</button>`:''}${!b.address?'<p class="muted">정확한 주소는 직접 입력해 주세요.</p>':mapLinks(b)}</article>`).join('')||'<p class="empty">등록된 예약이 없습니다.</p>'}`;}
function checklist(){const done=state.checks.filter(c=>c.done).length;return `<p class="eyebrow">BEFORE YOU GO</p><h1 class="page-title">Little preparations.</h1><div class="section-heading"><h2>여행 준비</h2><span class="meta">${done} / ${state.checks.length} 완료</span>${inlineTask('checks','')}</div><button data-hide-done="1">${hideDone?'완료 항목 표시':'완료 항목 접기'}</button><div class="progress" aria-hidden="true"><span style="width:${state.checks.length?done/state.checks.length*100:0}%"></span></div>${[...new Set([...groups,...state.checks.map(c=>c.group)])].map(g=>`<section class="check-group"><h3>${g}</h3>${state.checks.filter(c=>c.group===g&&(!hideDone||!c.done)).map(c=>`<div class="check-row ${c.done?'done':''}">${checkLabel(c,true,`<small class="meta"> ${esc(c.date||'')} ${esc(state.events.find(e=>e.id===c.eventId)?.title||state.bookings.find(b=>b.id===c.bookingId)?.title||'')}</small>`)}<button data-edit="checks" data-id="${esc(c.id)}" aria-label="${esc(c.title)} 수정">수정</button></div>`).join('')||'<p class="muted">등록된 항목이 없습니다.</p>'}</section>`).join('')}`;}

function render(){const focused=document.activeElement?.closest('[data-inline-task]')?.dataset.inlineTask;view=['home','itinerary','bookings','checklist'].includes(location.hash.slice(1))?location.hash.slice(1):'home';$('#main').innerHTML=({home,itinerary,bookings,checklist}[view])();$('#nav').innerHTML=navigation(view);hydrateImages();hydrateAttachments();if(focused)[...document.querySelectorAll('[data-inline-task]')].find(e=>e.dataset.inlineTask===focused)?.querySelector('input')?.focus();if(view==='itinerary'){const active=$('.date.active'),strip=$('.dates');if(active&&strip)strip.scrollLeft=active.offsetLeft-strip.offsetLeft-strip.clientWidth/2+active.clientWidth/2;}}
const field=(key,label,value='',type='text',options=null,wide=false)=>`<label class="field ${wide?'wide':''}">${label}${options?`<select name="${key}">${[...options,...(value&&!options.some(o=>(Array.isArray(o)?o[0]:o)===value)?[[value,value]]:[])].map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`;}).join('')}</select>`:type==='textarea'?`<textarea name="${key}" maxlength="20000">${esc(value)}</textarea>`:`<input name="${key}" type="${type}" value="${esc(value)}" ${key==='title'?'required maxlength="300"':'maxlength="20000"'} ${type==='date'?'min="2026-12-02" max="2026-12-15"':''} ${type==='url'?'placeholder="https://…"':''}>`}</label>`;
function openEditor(kind,id){const item=id?normalize(state[kind].find(x=>x.id===id)):{date:selected,city:cityFor(selected||dates[0]),status:'확인 필요',category:'관광',type:'숙소',group:groups[0]};editing={kind,id};$('#dialog-title').textContent=({events:'일정',bookings:'예약',checks:'준비 항목'}[kind])+(id?' 수정':' 추가');$('#form-error').textContent='';$('#form-actions').hidden=false;$('#delete').hidden=!id;let h=field('title','이름 / 제목 *',item.title,'text',null,true);
if(kind==='events'){h+=field('date','날짜',item.date,'text',[['','날짜 미정'],...dates])+field('city','도시',item.city,'text',cities)+field('start','시작 시간 · 현지 시각',item.start,'time')+field('end','종료 시간 · 현지 시각',item.end,'time')+field('category','카테고리',item.category,'text',['관광','성당','교회','박물관','미술관','전망대','공원','정원','공항','기차역','지하철역','버스 정류장','일반 장소','식사','카페','쇼핑','도보 이동','지하철','기차','버스','택시','항공','숙소','짐 보관','메모','선택 일정','대체 일정','배','차량','체크인','체크아웃','관람','전망','전시','이동','휴식','기타'])+field('status','예약 상태',item.status,'text',['미정','확인 필요','예약 예정','예약 완료','예약 불필요']);for(const [k,l,t]of [['address','주소'],['description','상세 설명','textarea'],['transport','이동 수단'],['duration','예상 소요 시간'],['origin','길찾기 출발지'],['route','이동 경로'],['cost','비용 (통화 포함)'],['local','현지어 주소 / 안내'],['map','지도 링크 (선택)','url'],['image','참고 이미지 URL (온라인)','url'],['note','메모','textarea']])h+=field(k,l,item[k],t||'text',null,['description','note'].includes(k));h+=field('mode','기존 이동 / 지도 방식 (호환)',item.mode||'','text',[['','선택 안 함'],['walk','도보'],['subway','지하철'],['train','기차'],['bus','버스'],['taxi','택시'],['flight','항공'],['ferry','배'],['car','차량'],['walking','도보'],['transit','대중교통'],['driving','자동차'],['bicycling','자전거']]);}
if(kind==='bookings'){h+=field('city','도시',item.city,'text',cities)+field('type','예약 종류',item.type,'text',['숙소','항공편','기차','공항 이동','기타 교통편'])+field('checkin','체크인 / 출발일',item.checkin,'date')+field('checkout','체크아웃 / 도착일',item.checkout,'date')+field('status','예약 상태',item.status,'text',['미정','확인 필요','예약 예정','예약 완료','예약 불필요']);for(const [k,l]of [['address','주소'],['instructions','체크인 / 탑승 안내'],['contact','연락처'],['reference','예약번호']])h+=field(k,l,item[k],['instructions','note'].includes(k)?'textarea':'text',null,true);}
if(kind==='checks')h+=field('group','카테고리 (직접 입력)',item.group)+field('date','날짜',item.date||'','text',[['','전체 여행'],...dates])+field('eventId','연결 일정',item.eventId||'','text',[['','연결 안 함'],...state.events.map(e=>[e.id,e.title])]);$('#fields').innerHTML=`<div class="form-grid">${h}</div>`;enhanceForm(kind,item);phase4Form(kind,item);phase5Form(kind,item);if(kind==='events')simplifyEventEditor(item,field);for(const input of document.querySelectorAll('#fields input[type=number]')){input.step='any';input.min='0';}$('#editor').showModal();}
$('#close').onclick=()=>$('#editor').close();
$('#form').onsubmit=async e=>{e.preventDefault();if(!editing)return;if(editing.kind==='dayNotes'){const next=clone();next.dayNotes={...next.dayNotes,[selected]:Object.fromEntries(new FormData(e.target))};try{validate(next);}catch(err){$('#form-error').textContent=err.message;return;}if(commit(next)){$('#editor').close();render();}return;}const {kind,id}=editing,next=clone(),old=next[kind].find(x=>x.id===id),values=Object.fromEntries(new FormData(e.target));values.title=values.title.trim();if(kind==='events'){values.transitStops=editorTransport();values.line=values.lineName;try{values.embedUrl=extractEmbed(values._embed||'');delete values._embed;}catch(err){$('#form-error').textContent=err.message;return;}if(values.reservationId&&next.events.some(e=>e.id!==id&&e.date===values.date&&e.reservationId===values.reservationId)){$('#form-error').textContent='이 날짜에 이미 연결된 예약입니다. 기존 연결 일정을 수정해 주세요.';return;}}try{await phase4Values(kind,values,old);}catch(err){$('#form-error').textContent=err.message;return;}if(kind==='events'&&values.start&&values.end&&values.end<values.start){$('#form-error').textContent='종료 시간이 시작 시간보다 빠릅니다. 다음 날 이동은 날짜별로 나누어 입력해 주세요.';return;}const file=$('#image-file')?.files[0];if(file){try{values.imageId=await putImage(file);}catch(err){$('#form-error').textContent=err.message;return;}}if($('#remove-image')?.checked){values.image='';values.imageId='';}const item={...(old||{}),...values,id:id||crypto.randomUUID()};if(kind==='events')for(const [alias,key]of Object.entries({placeUrl:'map',mapUrl:'map',directionsUrl:'directions',streetViewUrl:'streetview',websiteUrl:'website',originLabel:'origin',destinationLabel:'destination',reservationStatus:'status',importance:'condition',fare:'amount',localAddress:'local',memo:'note'}))if(old&&Object.hasOwn(old,alias))item[alias]=values[key]??old[alias];if(kind==='events'&&old&&old.date!==item.date)delete item.sortOrder;const conflict=timeConflict(item,kind);if(conflict&&!confirm(`입력한 현지 시각 차이는 ${conflict.actual}분, 소요 시간은 ${conflict.saved}분입니다. 시차나 대기 시간을 확인한 뒤 입력값 그대로 저장할까요?`))return;if(kind==='events'&&!id)item.order=Date.now();if(kind==='checks'&&!id)item.done=false;try{validate({...next,[kind]:id?next[kind].map(x=>x.id===id?item:x):[...next[kind],item]});}catch(err){$('#form-error').textContent=err.message;return;}next[kind]=id?next[kind].map(x=>x.id===id?item:x):[...next[kind],item];if(commit(next)){$('#editor').close();render();}};
$('#delete').onclick=()=>{if(!editing?.id||!confirm('이 항목을 삭제할까요? 삭제 전 백업하면 복원할 수 있습니다.'))return;const next=clone();next[editing.kind]=next[editing.kind].filter(x=>x.id!==editing.id);if(commit(next)){$('#editor').close();render();}};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.shift){const i=dates.indexOf(selected);selected=dates[Math.max(0,Math.min(dates.length-1,i+Number(b.dataset.shift)))];render();}if(b.dataset.today){const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());if(dates.includes(today)){selected=today;render();}else toast('오늘은 여행 기간 밖입니다.');}if(b.dataset.optional){hideOptional=!hideOptional;render();}if(b.dataset.hideDone){hideDone=!hideDone;render();}if(b.dataset.daynote)openDayNote();if(b.dataset.local)showPreview(b.dataset.local,b.dataset.caption);if(b.dataset.zoom)showPreview('',b.dataset.caption,b.dataset.zoom);if(b.hasAttribute('data-day')){selected=b.dataset.day;if(view==='itinerary')render();else location.hash='itinerary';}if(b.hasAttribute('data-select')){selected=b.dataset.select;render();}if(b.dataset.add)openEditor(b.dataset.add);if(b.dataset.edit)openEditor(b.dataset.edit,b.dataset.id);if(b.dataset.copy){try{await navigator.clipboard.writeText(b.dataset.copy);toast('주소를 복사했습니다');}catch{toast('복사할 수 없습니다. 표시된 주소를 길게 눌러 복사해 주세요.');}}if(b.dataset.move){if(commit(reorder(state,b.dataset.id,Number(b.dataset.move))))render();}});
document.addEventListener('change',e=>{if(e.target.dataset.check){const next=clone();next.checks.find(x=>x.id===e.target.dataset.check).done=e.target.checked;if(!commit(next))e.target.checked=!e.target.checked;render();}});
function download(content,name){const url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#settings').onclick=()=>{editing=null;$('#dialog-title').textContent='데이터 & 앱';$('#form-error').textContent='';$('#form-actions').hidden=true;$('#fields').innerHTML=`<p class="notice">이 브라우저에 자동 저장됩니다. 빈 기기에서 로그인하면 기존 클라우드 기록을 자동으로 받습니다. 로컬 데이터가 있으면 별도 확인 후 연결합니다. 브라우저 데이터 삭제 시 기록이 사라집니다. 백업 파일에는 직접 입력한 예약 정보도 포함됩니다. 첨부 이미지 파일은 IndexedDB에 별도 저장되며 JSON 백업에 포함되지 않습니다. 이미지 URL만 백업됩니다.</p>${blocked?'<p class="danger">기존 저장 데이터를 읽지 못했습니다. 원본 백업을 먼저 내려받은 뒤 올바른 백업을 가져오거나 초기화해 주세요.</p>':''}<div class="settings-actions"><button type="button" id="export">JSON 백업 내보내기</button><button type="button" id="import">JSON 백업 가져오기</button><input type="file" id="file" accept="application/json,.json" hidden><button type="button" id="install">홈 화면에 추가</button><button type="button" id="reset" class="danger">모든 데이터 초기화</button></div><p class="hint" id="pwa-info">처음 온라인으로 연 뒤 오프라인 준비 완료 안내를 확인하세요. 지도와 외부 이미지는 오프라인에서 사용할 수 없습니다.</p>`;$('#editor').showModal();phase4Settings();mountSyncSettings();$('#export').onclick=()=>{if(blocked){try{download(localStorage.getItem('europe-journal.user.v1')||'{}','europe-recovery.json');}catch{toast('브라우저 저장소에 접근할 수 없습니다.');}}else download(JSON.stringify({...state},null,2),`europe-2026-${new Date().toISOString().slice(0,10)}.json`);};$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('백업 파일은 5MB 이하만 지원합니다.');const next=validate(JSON.parse(await file.text()));if(!confirm(`일정 ${next.events.length}개, 예약 ${next.bookings.length}개, 준비 항목 ${next.checks.length}개로 현재 데이터를 덮어쓸까요?`))return;state=write(next,state,true);blocked=false;status();$('#editor').close();render();toast('백업을 복원했습니다');}catch(err){$('#form-error').textContent='가져오기 실패: '+err.message;}e.target.value='';};$('#reset').onclick=()=>{if(!confirm('직접 입력한 일정·예약·체크리스트를 모두 지우고 기본 여행 정보로 초기화할까요? 먼저 백업을 권장합니다.'))return;try{const next=defaults();state=write(next,state,true);blocked=false;status();$('#editor').close();render();toast('기본 여행 정보로 초기화했습니다');}catch{toast('초기화하지 못했습니다. 저장소 접근을 확인해 주세요.');}};$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;}else $('#pwa-info').textContent='iPhone/iPad: Safari에서 공유 → 홈 화면에 추가. Android: Chrome 메뉴 → 홈 화면에 추가 또는 앱 설치. HTTPS 또는 localhost에서 열어야 합니다.';};};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});window.addEventListener('online',status);window.addEventListener('offline',status);window.addEventListener('storage',e=>{if(e.key==='europe-journal.user.v1'){try{if($('#editor').open)return;state=read();blocked=false;render();status();toast('다른 탭의 변경 사항을 반영했습니다');}catch{blocked=true;status();}}});

function summaryHTML(d,compact=false){const items=list(d),s=summary(items),n=state.dayNotes?.[d]||{};return `<section class="day-summary"><p>${esc(s.places)}</p><p class="meta">시작 ${s.start} · 종료 ${s.end} · 선택 ${s.optional}개</p>${compact?`<p class="meta">주요 교통: ${esc(items.filter(e=>transitTypes.includes(e.category)).map(e=>e.title).join(' → ')||'미입력')}</p>`:`<p class="meta">예상 이동 ${s.travel} · 교통비 ${esc(s.transportCost)} · 하루 비용 ${esc(s.cost)}</p><p class="meta">일몰 ${esc(n.sunset||'미입력')} · 숙소 복귀 ${esc(n.returnTime||'미입력')}</p>${n.note?`<p>${esc(n.note)}</p>`:''}${n.routeUrl?`<a class="day-route" href="${esc(n.routeUrl)}" target="_blank" rel="noopener noreferrer">하루 전체 경로 보기 ↗</a>`:''}<small class="meta">비용 합계는 금액·통화를 입력한 일정만 포함합니다. 미입력 항목은 합계에서 제외됩니다.</small>`}</section>`;}
