function localHTML(e){return e.local?`<div class="actions"><button data-copy="${esc(e.local)}">현지어 복사</button><button data-local="${esc(e.local)}" data-caption="${esc([e.localDescription,e.pronunciation].filter(Boolean).join(' · '))}">현지어 크게 보기</button></div>`:'';}
let imageURLs=[];
async function hydrateImages(){imageURLs.forEach(URL.revokeObjectURL);imageURLs=[];for(const img of document.querySelectorAll('.reference-image')){img.onerror=()=>{img.hidden=true;img.closest('figure').querySelector('figcaption').textContent='이 기기에 이미지 원본이 없거나 연결할 수 없습니다. 원본 파일은 자동 동기화되지 않으며 전체 ZIP 백업으로 옮길 수 있습니다.';};img.onload=()=>img.closest('figure')?.style.setProperty('--natural-width',img.naturalWidth+'px');img.onclick=()=>showPreview('',img.alt,img.src);if(img.dataset.imageId){try{const blob=await getImage(img.dataset.imageId);if(!blob)throw Error();const url=URL.createObjectURL(blob);imageURLs.push(url);if(img.isConnected)img.src=url;}catch{img.onerror();}}}}
