let attachmentDraft=[],pendingFiles=new Map(),attachmentURLs=[];
const bookingIcon=b=>b.iconType||({'숙소':'bed','항공편':'flight','기차':'train','투어':'pin','티켓':'ticket'}[b.type]||'ticket');
function linkedChecks(kind,id){const event=kind==='events'?state.events.find(e=>e.id===id):null;const checks=state.checks.filter(c=>kind==='events'?(c.eventId===id||c.eventIds?.includes(id)||(event?.reservationId&&c.bookingId===event.reservationId)):c.bookingId===id);return `<section class="linked-checks"><h4>할 일 (${checks.filter(c=>c.done).length}/${checks.length} 완료)</h4>${checks.map(c=>`<div class="check-row"><label><input type="checkbox" data-check="${esc(c.id)}" ${c.done?'checked':''}>${esc(c.title)}</label><button data-edit="checks" data-id="${esc(c.id)}">수정</button></div>`).join('')}${inlineTask(kind,id)}</section>`;}
function linkedBooking(b){return `<article class="booking linked-booking">${bookingHeading(b)}<p>${esc(b.type)} · ${esc(b.checkin||'')} ${esc(b.checkinTime||'')} → ${esc(b.checkout||'')} ${esc(b.checkoutTime||'')}</p>${b.origin||b.destination||b.serviceNumber?`<p>${esc(b.origin)} → ${esc(b.destination)} · ${esc(b.serviceNumber||'')}</p>`:''}<button data-edit="bookings" data-id="${esc(b.id)}">예약 상세 / 수정</button>${attachmentsHTML(b)}${linkedChecks('bookings',b.id)}</article>`;}
function attachmentsHTML(x){const type=x.type||x.category,tone=type==='기차'?'train':['항공','항공편'].includes(type)?'flight':type==='숙소'?'stay':'other';return `<div class="attachments media-content">${(x.attachments||[]).map(a=>`<figure data-attachment="${esc(a.id)}" data-filename="${esc(a.name)}" data-ratio="${esc(a.ratio||'original')}" class="${a.type==='application/pdf'?'pdf-attachment ticket-'+tone:'image-attachment'}">${a.type==='application/pdf'?`<div class="pdf-heading">${icon('file')}<strong>${esc(a.name)}</strong><small>PDF · ${a.size<1024?a.size+' B':(a.size/1024).toFixed(1)+' KB'}</small></div>`:`<div class="image-frame"><img alt="${esc(a.caption||a.name)}" loading="lazy"></div><figcaption>${esc(a.caption||a.name)}</figcaption>`}<span class="attachment-links"></span></figure>`).join('')}</div>`;}
async function hydrateAttachments(){attachmentURLs.forEach(URL.revokeObjectURL);attachmentURLs=[];for(const el of document.querySelectorAll('[data-attachment]')){try{const blob=await getImage(el.dataset.attachment);if(!blob)throw Error();if(!el.isConnected)continue;const url=URL.createObjectURL(blob);attachmentURLs.push(url);const img=el.querySelector('img');if(img){img.onload=()=>el.style.setProperty('--natural-width',img.naturalWidth+'px');img.src=url;img.onclick=()=>showPreview('',img.alt,url);}const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener';link.textContent='열기 ↗';const save=link.cloneNode();save.textContent='파일 저장';save.download=el.dataset.filename||'attachment';el.querySelector('.attachment-links').append(link,save);}catch{el.querySelector('.attachment-links').textContent='이 기기에 원본이 없습니다. 전체 ZIP 백업으로 복원해 주세요.';}}}
function attachmentEditor(){const host=$('#attachment-list');if(!host)return;host.innerHTML=attachmentDraft.map((a,i)=>`<div class="attachment-edit"><span>${esc(a.name)} · ${(a.size/1024).toFixed(0)} KB</span>${a.type.startsWith('image/')?`<label>표시 비율<select data-file-ratio="${i}" aria-label="${esc(a.name)} 표시 비율">${imageRatios.map(r=>`<option value="${r}" ${r===(a.ratio||'original')?'selected':''}>${r==='original'?'원본 비율':r}</option>`).join('')}</select></label><div class="image-ratio-preview" data-ratio="${esc(a.ratio||'original')}"><img data-draft-image="${esc(a.id)}" alt="비율 미리보기"></div>`:''}<input aria-label="${esc(a.name)} 설명" data-caption-id="${esc(a.id)}" value="${esc(a.caption||'')}" placeholder="이미지 설명"><button type="button" data-file-shift="${i}" data-delta="-1" ${i===0?'disabled':''}>↑</button><button type="button" data-file-shift="${i}" data-delta="1" ${i===attachmentDraft.length-1?'disabled':''}>↓</button><label class="replace-file">교체<input type="file" data-file-replace="${i}" accept="image/jpeg,image/png,image/webp,application/pdf"></label><button type="button" data-file-remove="${i}">삭제</button></div>`).join('');hydrateDraftImages();}
