 if(values._amount!==''){if(!values._currency)throw Error('예상 비용: 통화를 선택해 주세요.');values.amount=values._amount;values.currency=values._currency;values.cost='';}else if(moneyOf(old||{})){values.amount='';values.currency=values._currency;values.cost='';}
