function fallbackHTML(e){const x=normalize(e),urls=[['Google Maps에서 열기',mapURLs(x).map],['Street View',mapURLs(x).street],['출발지 Street View',streetURL(x.originStreetViewUrl)],['도착지 Street View',streetURL(x.destinationStreetViewUrl)]];return `<div class="actions">${urls.filter(([,u])=>u).map(([label,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`).join('')}</div>`;}
function streetEmbed(e){const src=validEmbedURL(e.embedUrl),configured=src||e.pano||(e.latitude!==undefined&&e.latitude!==''&&e.longitude!==undefined&&e.longitude!=='');const external=mapURLs(e).street||streetURL(e.originStreetViewUrl)||streetURL(e.destinationStreetViewUrl);if(!configured&&!external)return '';return `<details class="street-embed media-content" data-event-id="${esc(e.id)}" open><summary>${src?embedKind(src):'Street View'}</summary><div class="street-frame"></div><button class="embed-problem" type="button">화면 표시 문제</button><div class="embed-fallback" hidden>${fallbackHTML(e)}</div></details>`;}
document.addEventListener('toggle',e=>{const d=e.target;if(!d.matches?.('.street-embed'))return;const host=d.querySelector('.street-frame');if(!d.open){host.replaceChildren();return;}if(host.querySelector('iframe'))return;const item=state.events.find(x=>x.id===d.dataset.eventId);if(!item)return;let src=validEmbedURL(item.embedUrl);const fallback=d.querySelector('.embed-fallback');if(!src){const key=localStorage.getItem('europe-journal.embed-key');if(!key||(!item.pano&&(item.latitude===undefined||item.latitude===''||item.longitude===undefined||item.longitude===''))){host.textContent='인앱 표시 설정을 확인해 주세요. 외부 링크로 열 수 있습니다.';fallback.hidden=false;return;}const url=new URL('https://www.google.com/maps/embed/v1/streetview');url.searchParams.set('key',key);if(item.pano)url.searchParams.set('pano',item.pano);else url.searchParams.set('location',item.latitude+','+item.longitude);src=url.href;}const frame=document.createElement('iframe');frame.src=src;frame.title='Google Maps 지도 또는 Street View 파노라마';frame.allowFullscreen=true;frame.referrerPolicy='no-referrer-when-downgrade';frame.loading='lazy';frame.onerror=()=>{fallback.hidden=false;};host.append(frame);},true);
