function setupEmbedEditor(item){const input=$('[name="_embed"]'),label=input.closest('label'),section=label.parentElement;label.hidden=!!item.embedUrl;const status=document.createElement('div');status.className='embed-registration';status.innerHTML=`<p>${item.embedUrl?'Google Maps 등록 완료 · '+esc(embedKind(item.embedUrl)):'Google Maps 퍼가기 코드 등록'}</p><button type="button" data-embed-preview>미리보기</button><button type="button" data-embed-change>코드 변경</button><button type="button" data-embed-delete>삭제</button>`;section.insertBefore(status,label);status.querySelector('[data-embed-change]').onclick=()=>{label.hidden=false;input.focus();};status.querySelector('[data-embed-delete]').onclick=()=>{if(confirm('지도 연결을 삭제할까요? 저장하기 전에는 기존 연결이 유지됩니다.')){input.value='';label.hidden=false;status.querySelector('p').textContent='저장 시 지도 연결을 삭제합니다.';}};status.querySelector('[data-embed-preview]').onclick=()=>{try{const src=extractEmbed(input.value);if(!src)throw Error('먼저 퍼가기 코드를 입력해 주세요.');showPreview('');const d=$('#preview'),frame=document.createElement('iframe');frame.className='embed-preview-frame';frame.src=src;frame.title='Google Maps 미리보기';frame.allowFullscreen=true;d.append(frame);}catch(err){$('#form-error').textContent=err.message;}};}
