function phase4Settings(){const host=$('.settings-actions');host.insertAdjacentHTML('beforeend','<button type="button" id="zip-export">첨부 포함 전체 ZIP 백업</button><label>전체 ZIP 복원<input type="file" id="zip-import" accept=".zip,application/zip"></label><label>Google Maps Embed API 키<input id="embed-key" type="password" autocomplete="off"></label><button type="button" id="embed-save">API 키 저장</button><p class="hint">Maps Embed API 활성화와 웹사이트 제한이 설정된 키가 필요합니다. API 키는 이 브라우저에만 저장되며 백업에서 제외됩니다.</p>');$('#embed-key').value=localStorage.getItem('europe-journal.embed-key')||'';$('#embed-save').onclick=()=>{try{localStorage.setItem('europe-journal.embed-key',$('#embed-key').value.trim());toast('API 키를 저장했습니다');}catch{toast('API 키 저장 실패');}};$('#zip-export').onclick=async()=>{try{if(blocked)throw Error('저장 데이터 오류를 먼저 복구해 주세요.');$('#zip-export').disabled=true;saveBlob(await exportZIP(state),'europe-full-backup.zip');toast('전체 ZIP 백업을 생성했습니다');}catch(err){$('#form-error').textContent=err.message;}finally{$('#zip-export').disabled=false;}};$('#zip-import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const {data,entries}=await importZIP(f,validate);if(!confirm(`일정 ${data.events.length}개, 예약 ${data.bookings.length}개와 첨부 ${entries.length}개를 복원하여 현재 데이터를 교체할까요?`))return;await storeFiles(entries);state=write(data,state,true);blocked=false;$('#editor').close();render();status();toast('전체 백업을 복원했습니다');}catch(err){$('#form-error').textContent='ZIP 복원 실패: '+err.message;}};}

