document.addEventListener('change',e=>{if(e.target.dataset.fileReplace!==undefined){try{const file=e.target.files[0];if(!file)return;checkFile(file);const i=+e.target.dataset.fileReplace,id=crypto.randomUUID(),old=attachmentDraft[i];attachmentDraft[i]={...old,id,name:file.name,type:file.type,size:file.size,createdAt:new Date().toISOString()};pendingFiles.set(id,file);attachmentEditor();}catch(err){$('#form-error').textContent=err.message;}}});
