 if(b.dataset.transfer){const item=state.events.find(x=>x.id===b.dataset.transfer),copy=b.dataset.copyEvent==='1';actionDialog(copy?'다른 날짜로 복사':'다른 날짜로 이동',field('date','대상 날짜',item.date,'text',dates)+field('city','대상 도시 (직접 입력 가능)',cityFor(item.date)),values=>{if(!values.city.trim())throw Error('도시를 입력해 주세요.');const next=transfer(state,item.id,values.date,values.city.trim(),copy);if(item.reservationId&&next.events.filter(x=>x.date===values.date&&x.reservationId===item.reservationId).length>1)throw Error('대상 날짜에 이 예약이 이미 연결되어 있습니다.');if(!commit(next))return false;selected=values.date;render();});const date=$('#action-dialog [name="date"]');date.onchange=()=>$('#action-dialog [name="city"]').value=cityFor(date.value);}
