function inlineTask(kind,id){const key=kind+':'+id,d=taskDrafts.get(key)||{open:false,text:'',error:''};return `<div class="inline-task" data-inline-task="${esc(key)}" data-task-kind="${kind}" data-task-id="${esc(id)}"><button type="button" data-inline-open>할 일 추가 +</button><div class="inline-task-entry" ${d.open?'':'hidden'}><input aria-label="할 일 입력" placeholder="할 일 입력" maxlength="300" value="${esc(d.text)}"><button type="button" data-inline-save aria-label="할 일 저장">✓</button><p role="status">${esc(d.error)}</p></div></div>`;}
function saveInlineTask(host){const key=host.dataset.inlineTask,input=host.querySelector('input'),title=input.value.trim(),d=taskDrafts.get(key)||{open:true,text:input.value};if(!title){d.error='할 일을 입력해 주세요.';taskDrafts.set(key,d);host.querySelector('[role=status]').textContent=d.error;input.focus();return;}
 const next=clone(),kind=host.dataset.taskKind,id=host.dataset.taskId,event=next.events.find(e=>e.id===id),booking=next.bookings.find(e=>e.id===id);const task={id:crypto.randomUUID(),title,group:groups[0],done:false};if(kind==='events'){task.eventId=id;task.date=event?.date||'';}if(kind==='bookings'){task.bookingId=id;task.date=booking?.checkin||'';}next.checks.push(task);
 if(!commit(next)){d.error='저장하지 못했습니다. 입력 내용은 유지됩니다.';taskDrafts.set(key,d);host.querySelector('[role=status]').textContent=d.error;return;}taskDrafts.set(key,{open:true,text:'',error:''});render();[...document.querySelectorAll('[data-inline-task]')].find(e=>e.dataset.inlineTask===key)?.querySelector('input').focus();}
document.addEventListener('input',e=>{const host=e.target.closest('[data-inline-task]');if(host&&e.target.matches('input'))taskDrafts.set(host.dataset.inlineTask,{open:true,text:e.target.value,error:''});});
document.addEventListener('keydown',e=>{const host=e.target.closest('[data-inline-task]');if(!host||e.isComposing)return;if(e.key==='Enter'){e.preventDefault();saveInlineTask(host);}if(e.key==='Escape'){e.preventDefault();taskDrafts.delete(host.dataset.inlineTask);render();}});
document.addEventListener('click',e=>{const b=e.target.closest('button'),host=b?.closest('[data-inline-task]');if(!host)return;if(b.hasAttribute('data-inline-open')){const input=host.querySelector('input');taskDrafts.set(host.dataset.inlineTask,{open:true,text:input.value,error:''});host.querySelector('.inline-task-entry').hidden=false;input.focus();}if(b.hasAttribute('data-inline-save'))saveInlineTask(host);});
async function hydrateDraftImages(){for(const image of document.querySelectorAll('[data-draft-image]')){try{const blob=pendingFiles.get(image.dataset.draftImage)||await getImage(image.dataset.draftImage);if(blob&&image.isConnected){const url=URL.createObjectURL(blob);attachmentURLs.push(url);image.src=url;}}catch{}}}
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-file-ratio')){const a=attachmentDraft[+e.target.dataset.fileRatio];a.ratio=e.target.value;e.target.closest('.attachment-edit').querySelector('.image-ratio-preview').dataset.ratio=e.target.value;}});
